export interface Task { id?: string; title: string; prompt: string; frequency: string; at: string; weekday: number; timeZone: string; mode?: 'plan' | 'manual' | 'bypass'; enabled: boolean; archived?: boolean; nextRunAt?: string; lastRunAt?: string; status?: string; output?: string; demo?: boolean; error?: string; attention?: string | null; /** The files the last run made or changed (name, full path). */ files?: { name: string; path: string }[]; /** When the last run ended, and one plain sentence of its answer (the board's card line). */ finishedAt?: string | null; lastLine?: string | null; /** The person dismissed this run's card on the board. A new run clears it. */ ackedAt?: string | null; }
export const blankTask = (): Task => ({ title:'', prompt:'', frequency:'daily', at:'09:00', weekday:1, timeZone:Intl.DateTimeFormat().resolvedOptions().timeZone, mode:'bypass', enabled:true });
